<script setup lang="ts">import type {Result} from '../types/entities';import PathRibbon from './PathRibbon.vue';import {operations} from '../constants/enums';import {label} from '../utils/path';defineProps<{result:Result}>();function cost(o:{operation:string;cost?:number},result:Result){if(o.cost!==undefined)return o.cost;if(o.operation==='keep')return 0;const c=result.edit_costs;if(c)return c[o.operation as 'insert'|'delete'|'substitute'];const s:any=result.study||{};return s[o.operation+'_cost']??1}</script><template><div class="alignment-list"><article v-for="a in result.alignments" :key="a.exited_path.join('>')"><header><b>退出路径 × {{a.frequency}}</b><span>加权距离 {{a.distance}} · 成本合计 {{a.total_cost??a.distance}}</span></header><PathRibbon :path="a.exited_path" :dictionary="result.dictionary" compact/><p class="align-caption">最近成功路径（退出路径→成功路径同方向）</p><PathRibbon :path="a.converted_path" :dictionary="result.dictionary" compact/><div class="edit-operations"><span v-for="(o,i) in a.operations" :key="i" :class="o.operation">{{operations[o.operation]}} {{o.from?label(o.from,result.dictionary):'—'}}<template v-if="o.operation!=='keep'"> → {{o.to?label(o.to,result.dictionary):'—'}} · 成本{{cost(o,result)}}</template></span></div></article><p v-if="!result.alignments.length" class="annotation">需要同时有转化组和退出组，才能显示最近成功路径对齐。</p></div></template>
